  return <><section className="page-title-row"><div><p className="section-kicker">CANDIDATE PROFILE</p><h1>Give recruiters the full picture.</h1><p>Keep the essentials fresh so we can surface stronger opportunities.</p></div><div className="profile-score-small"><ProgressRing value={strength} size={60} /><span>Profile strength</span></div></section><form className="profile-form-v2" onSubmit={(event) => { event.preventDefault(); onSave() }}><section><h2>Contact details</h2><p>How recruiters can recognize and reach you.</p><div className="form-two-columns"><label>Phone number<input value={profile.phone ?? ''} onChange={(event) => update('phone', event.target.value)} placeholder="e.g. 98765 43210" /></label><label>Current location<input value={profile.location ?? ''} onChange={(event) => update('location', event.target.value)} placeholder="e.g. Ghaziabad, India" /></label></div></section><section><h2>Your professional story</h2><p>Write a short, specific introduction. It also makes profile matching more useful.</p><label>About you<textarea rows="5" value={profile.bio ?? ''} onChange={(event) => update('bio', event.target.value)} placeholder="e.g. Software developer focused on clean interfaces, React and product thinking." /></label></section><section><h2>Links that strengthen your profile</h2><p>Add work that backs up your skills. All links are optional.</p><div className="form-two-columns"><label>LinkedIn URL<input type="url" value={profile.linkedinUrl ?? ''} onChange={(event) => update('linkedinUrl', event.target.value)} placeholder="https://linkedin.com/in/your-name" /></label><label>GitHub URL<input type="url" value={profile.githubUrl ?? ''} onChange={(event) => update('githubUrl', event.target.value)} placeholder="https://github.com/your-name" /></label><label>Portfolio URL<input type="url" value={profile.portfolioUrl ?? ''} onChange={(event) => update('portfolioUrl', event.target.value)} placeholder="https://yourportfolio.com" /></label></div></section><div className="form-submit-row"><p>✓ Your profile is visible only to recruiters when you apply.</p><button type="submit" className="primary-action" disabled={saving}>{saving ? 'Saving profile…' : 'Save profile'} <span>→</span></button></div></form></>
