function LegacyRecruiterApplications({ applications, jobs, onUpdate, updatingId }) {
  const [jobFilter, setJobFilter] = useState('')
  const visibleApplications = jobFilter ? applications.filter((item) => String(item.jobId) === jobFilter) : applications
  const jobById = new Map(jobs.map((job) => [job.id, job]))
  const countByStatus = (status) => applications.filter((item) => item.status === status).length

  return <><section className="page-title-row"><div><p className="section-kicker">CANDIDATE PIPELINE</p><h1>Turn strong applications into conversations.</h1><p>Review AI match signals and move every candidate through your hiring process.</p></div></section><section className="recruiter-pipeline-stats"><article><span>All candidates</span><b>{applications.length}</b></article><article><span>New applications</span><b>{countByStatus('APPLIED')}</b></article><article><span>Shortlisted</span><b>{countByStatus('SHORTLISTED')}</b></article><article><span>Hired</span><b>{countByStatus('HIRED')}</b></article></section><div className="pipeline-toolbar"><label>Role<select value={jobFilter} onChange={(event) => setJobFilter(event.target.value)}><option value="">All active roles</option>{jobs.map((job) => <option key={job.id} value={job.id}>{job.title} · {job.companyName}</option>)}</select></label><span>{visibleApplications.length} candidate{visibleApplications.length === 1 ? '' : 's'}</span></div>{visibleApplications.length ? <section className="candidate-pipeline-list">{visibleApplications.map((application) => { const job = jobById.get(application.jobId); const strengths = safelyParseList(application.strengths); const gaps = safelyParseList(application.missingSkills); const isUpdating = updatingId === application.id; return <article className="candidate-pipeline-card" key={application.id}><div className="pipeline-candidate"><span className="pipeline-avatar">C{application.candidateProfileId}</span><div><p>Candidate application #{application.id}</p><h3>{job?.title || `Role #${application.jobId}`}</h3><span>Applied {formatDate(application.appliedAt)} · Resume #{application.resumeId}</span></div></div><div className="pipeline-match">{application.matchScore == null ? <span className="analysis-pending"><i className="spinner" /> Analysing match</span> : <><b>{application.matchScore}%</b><span>AI match</span></>}</div><div className="pipeline-status"><label>Pipeline stage<select value={application.status} disabled={isUpdating} onChange={(event) => onUpdate(application.id, event.target.value)}><option value="APPLIED">Applied</option><option value="REVIEWING">Reviewing</option><option value="SHORTLISTED">Shortlisted</option><option value="REJECTED">Rejected</option><option value="HIRED">Hired</option></select></label>{isUpdating && <small><i className="spinner" /> Updating</small>}</div>{(application.matchReasoning || strengths.length || gaps.length) && <div className="pipeline-insight"><span>✦</span><div><b>AI match insight</b><p>{application.matchReasoning || 'The candidate match analysis is still being prepared.'}</p>{strengths.length > 0 && <div className="insight-tags">{strengths.slice(0, 4).map((skill) => <span className="positive" key={skill}>{skill}</span>)}{gaps.slice(0, 3).map((skill) => <span key={skill}>{skill}</span>)}</div>}</div></div>}</article> })}</section> : <EmptyState icon="◉" title="No candidates in this view" detail="As soon as candidates apply, their resumes and match signals will show up here." />}</>
}

