  if (tab === 'jobs') return <><section className="page-title-row"><div><p className="section-kicker">JOB MANAGEMENT</p><h1>Keep your hiring pipeline moving.</h1><p>Live jobs are visible to every verified candidate.</p></div><button type="button" className="primary-action compact" onClick={() => setTab('post')}>Post a job <span>+</span></button></section>{jobs.length ? <section className="explorer-grid">{jobs.map((item) => <JobCard key={item.id} job={item} onOpen={() => {}} onToggleSave={() => {}} />)}</section> : <EmptyState icon="▣" title="No roles posted yet" detail="Your next great hire starts with a clear role description." />}</>
  if (tab === 'applications') return <RecruiterApplications applications={applications} jobs={jobs} onUpdate={onUpdateApplication} updatingId={updatingApplicationId} />
  if (tab === 'post') return <><section className="page-title-row"><div><p className="section-kicker">CREATE OPPORTUNITY</p><h1>Write a role candidates want.</h1><p>Strong details lead to stronger AI matches.</p></div></section><form className="job-post-form" onSubmit={(event) => { event.preventDefault(); onPostJob(job, () => setJob(blankJob)) }}><label>Job title<input required value={job.title} onChange={(event) => updateJob('title', event.target.value)} placeholder="e.g. Senior Product Designer" /></label><label>Company name<input required value={job.companyName} onChange={(event) => updateJob('companyName', event.target.value)} placeholder="Your company" /></label><label>Location<input value={job.location} onChange={(event) => updateJob('location', event.target.value)} placeholder="e.g. Bengaluru, India" /></label><label>Salary range<input value={job.salaryRange} onChange={(event) => updateJob('salaryRange', event.target.value)} placeholder="e.g. ₹12–18 LPA" /></label><label>Work mode<select value={job.workMode} onChange={(event) => updateJob('workMode', event.target.value)}><option value="REMOTE">Remote</option><option value="HYBRID">Hybrid</option><option value="ONSITE">On-site</option></select></label><label>Job type<select value={job.jobType} onChange={(event) => updateJob('jobType', event.target.value)}><option value="FULL_TIME">Full time</option><option value="PART_TIME">Part time</option><option value="INTERNSHIP">Internship</option><option value="CONTRACT">Contract</option></select></label><label className="wide-field">Role description<textarea required rows="6" value={job.description} onChange={(event) => updateJob('description', event.target.value)} placeholder="Describe the impact, scope and day-to-day work." /></label><label className="wide-field">Requirements<textarea rows="5" value={job.requirements} onChange={(event) => updateJob('requirements', event.target.value)} placeholder="List the skills and experience that will help candidates succeed." /></label><button type="submit" className="primary-action job-submit" disabled={posting}>{posting ? 'Publishing…' : 'Publish role'} <span>→</span></button></form></>
  return <><section className="page-title-row"><div><p className="section-kicker">COMPANY PROFILE</p><h1>Help candidates know who they will join.</h1><p>Great candidates evaluate the company as carefully as the role.</p></div></section><form className="profile-form-v2" onSubmit={(event) => { event.preventDefault(); onSaveProfile() }}><section><h2>Company essentials</h2><div className="form-two-columns"><label>Company name<input value={profile.companyName ?? ''} onChange={(event) => updateProfile('companyName', event.target.value)} /></label><label>Company website<input type="url" value={profile.companyWebsite ?? ''} onChange={(event) => updateProfile('companyWebsite', event.target.value)} /></label><label>Your designation<input value={profile.designation ?? ''} onChange={(event) => updateProfile('designation', event.target.value)} /></label></div></section><section><h2>Why join your team?</h2><label>Company description<textarea rows="6" value={profile.companyDescription ?? ''} onChange={(event) => updateProfile('companyDescription', event.target.value)} /></label></section><div className="form-submit-row"><p>✓ A polished company profile builds candidate trust.</p><button type="submit" className="primary-action" disabled={saving}>{saving ? 'Saving…' : 'Save company profile'} <span>→</span></button></div></form></>
