function RecruiterWorkspace(props) {
  const { tab, setTab, jobs, applications, onUpdateApplication, updatingApplicationId } = props
  if (tab === 'overview') return <><section className="welcome-row"><div><p className="section-kicker">RECRUITER WORKSPACE</p><h1>Build the team that moves you forward.</h1><p>Manage roles and review candidate applications from one focused workspace.</p></div><button type="button" className="primary-action compact" onClick={() => setTab('post')}>Post a new job <span>+</span></button></section><section className="metric-grid recruiter-metrics"><article><span className="metric-icon violet">▣</span><div><b>{jobs.length}</b><p>Active roles</p></div><button type="button" onClick={() => setTab('jobs')}>Manage →</button></article><article><span className="metric-icon teal">◉</span><div><b>{applications.length}</b><p>Total candidates</p></div><button type="button" onClick={() => setTab('applications')}>Review →</button></article></section></>
  if (tab === 'jobs') return <><section className="page-title-row"><div><p className="section-kicker">JOB MANAGEMENT</p><h1>Keep your hiring pipeline moving.</h1><p>Open a role to review everyone who applied to it.</p></div><button type="button" className="primary-action compact" onClick={() => setTab('post')}>Post a job <span>+</span></button></section>{jobs.length ? <section className="explorer-grid">{jobs.map((job) => <JobCard key={job.id} job={job} onOpen={() => setTab('applications')} onToggleSave={() => {}} />)}</section> : <EmptyState icon="▣" title="No roles posted yet" detail="Your next great hire starts with a clear role description." />}</>
  if (tab === 'applications') return <RecruiterApplications applications={applications} jobs={jobs} onUpdate={onUpdateApplication} updatingId={updatingApplicationId} />
  return <LegacyRecruiterWorkspace {...props} />
}

export default function Dashboard({ user, onLogout }) {
  const isRecruiter = user.role === 'RECRUITER'; const [tab, setTab] = useState(isRecruiter ? 'overview' : 'home'); const [profile, setProfile] = useState(isRecruiter ? blankRecruiter : blankCandidate); const [jobs, setJobs] = useState([]); const [resumes, setResumes] = useState([]); const [applications, setApplications] = useState([]); const [recruiterApplications, setRecruiterApplications] = useState([]); const [savedIds, setSavedIds] = useState(() => readSavedJobs(user)); const [selectedJob, setSelectedJob] = useState(null); const [applyJob, setApplyJob] = useState(null); const [notice, setNotice] = useState(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [uploading, setUploading] = useState(false); const [generating, setGenerating] = useState(false); const [submittingApplication, setSubmittingApplication] = useState(false); const [updatingApplicationId, setUpdatingApplicationId] = useState(null); const [posting, setPosting] = useState(false); const [refreshToken, setRefreshToken] = useState(0); const [resumeDraft, setResumeDraft] = useState(blankResumeDraft)
  useEffect(() => { try { localStorage.setItem(localStorageKey(user), JSON.stringify(savedIds)) } catch { /* Browser storage is optional. */ } }, [savedIds, user])
  useEffect(() => {
    let cancelled = false
    async function loadWorkspace() {
      setLoading(true)
      const requests = isRecruiter ? [getRecruiterProfile(), listMyJobs()] : [getCandidateProfile(), listJobs(), listMyResumes(), listMyApplications()]
      const results = await Promise.allSettled(requests)
      if (cancelled) return
      const [profileResult, jobsResult, resumesResult, applicationsResult] = results
      const jobList = jobsResult.status === 'fulfilled' && Array.isArray(jobsResult.value) ? jobsResult.value : []
      if (profileResult.status === 'fulfilled') setProfile(profileResult.value ?? (isRecruiter ? blankRecruiter : blankCandidate))
      if (jobsResult.status === 'fulfilled') setJobs(jobList)
      if (!isRecruiter) {
        if (resumesResult?.status === 'fulfilled') setResumes(Array.isArray(resumesResult.value) ? resumesResult.value : [])
        if (applicationsResult?.status === 'fulfilled') setApplications(Array.isArray(applicationsResult.value) ? applicationsResult.value : [])
      }
      if (isRecruiter) {
        const applicationResults = await Promise.allSettled(jobList.map((job) => listJobApplications(job.id)))
        if (cancelled) return
        setRecruiterApplications(applicationResults.flatMap((result) => result.status === 'fulfilled' && Array.isArray(result.value) ? result.value : []))
      }
      const failed = results.find((result) => result.status === 'rejected')
      if (failed) setNotice({ kind: 'error', text: failed.reason?.message ?? 'Some workspace data could not be loaded.' })
      setLoading(false)
    }
    loadWorkspace()
    return () => { cancelled = true }
  }, [isRecruiter, refreshToken, user.id, user.userId])
  useEffect(() => { const analysisPending = resumes.some((resume) => resume.analysisStatus === 'PROCESSING') || applications.some((application) => application.matchScore == null); if (!isRecruiter && analysisPending) { const timer = window.setTimeout(() => setRefreshToken((current) => current + 1), 4500); return () => window.clearTimeout(timer) } return undefined }, [isRecruiter, resumes, applications])
  const skills = useMemo(() => candidateSkillSet(profile, resumes), [profile, resumes]); const appliedJobIds = useMemo(() => new Set(applications.map((application) => application.jobId)), [applications]); const tabs = isRecruiter ? recruiterTabs : candidateTabs
  function toggleSaved(jobId) { setSavedIds((current) => current.includes(jobId) ? current.filter((id) => id !== jobId) : [jobId, ...current]) }
  async function saveProfile() { setSaving(true); try { const payload = isRecruiter ? { companyName: profile.companyName ?? '', companyWebsite: profile.companyWebsite ?? '', designation: profile.designation ?? '', companyDescription: profile.companyDescription ?? '' } : { phone: profile.phone ?? '', location: profile.location ?? '', linkedinUrl: profile.linkedinUrl ?? '', githubUrl: profile.githubUrl ?? '', portfolioUrl: profile.portfolioUrl ?? '', bio: profile.bio ?? '' }; const saved = await (isRecruiter ? saveRecruiterProfile(payload) : saveCandidateProfile(payload)); setProfile(saved); setNotice({ kind: 'success', text: 'Profile saved successfully. Your workspace is up to date.' }) } catch (error) { setNotice({ kind: 'error', text: error.message }) } finally { setSaving(false) } }
  async function postJob(job, reset) { setPosting(true); try { const created = await createJob(job); setJobs((current) => [created, ...current]); reset(); setNotice({ kind: 'success', text: 'Role published. Candidates can now discover it.' }); setTab('jobs') } catch (error) { setNotice({ kind: 'error', text: error.message }) } finally { setPosting(false) } }
  async function handleUpload(file) { if (file.size > 5 * 1024 * 1024) { setNotice({ kind: 'error', text: 'Please choose a PDF smaller than 5 MB.' }); return } setUploading(true); try { const created = await uploadResume(file); setResumes((current) => [created, ...current]); setNotice({ kind: 'success', text: 'Resume uploaded. AI analysis is now running in the background.' }) } catch (error) { setNotice({ kind: 'error', text: error.message }) } finally { setUploading(false) } }
  async function handleGenerateResume() { setGenerating(true); try { const created = await generateResume(resumeDraft); setResumes((current) => [created, ...current]); setNotice({ kind: 'success', text: 'Your AI resume draft is ready and can now be used to apply.' }) } catch (error) { const missingEndpoint = error.status === 404 || error.status === 405; setNotice({ kind: 'error', text: missingEndpoint ? 'Resume generation is ready in the frontend. Restart the updated backend once to enable this action.' : error.message }) } finally { setGenerating(false) } }
  function beginApply(job) { if (appliedJobIds.has(job.id)) return; if (!resumes.length) { setNotice({ kind: 'error', text: 'Add or build a resume before applying. We have opened Resume Studio for you.' }); setTab('resumes'); setSelectedJob(null); return } setApplyJob(job) }
  async function submitApplication(resumeId) { if (!applyJob) return; setSubmittingApplication(true); try { const created = await applyToJob({ jobId: applyJob.id, resumeId }); setApplications((current) => [created, ...current]); setApplyJob(null); setSelectedJob(null); setNotice({ kind: 'success', text: `Application sent to ${applyJob.companyName}. We are preparing your match insight.` }); setTab('applications') } catch (error) { setNotice({ kind: 'error', text: error.message }) } finally { setSubmittingApplication(false) } }
  async function handleRecruiterStatus(applicationId, status) {
    setUpdatingApplicationId(applicationId)
    try {
      const updated = await updateApplicationStatus(applicationId, status)
      setRecruiterApplications((current) => current.map((application) => application.id === applicationId ? updated : application))
      setNotice({ kind: 'success', text: `Candidate moved to ${pretty(status)}.` })
    } catch (error) {
      setNotice({ kind: 'error', text: error.message })
    } finally {
      setUpdatingApplicationId(null)
    }
  }
  useEffect(() => { const openApplications = () => { setTab('applications'); setSelectedJob(null) }; window.addEventListener('smarthire:open-applications', openApplications); return () => window.removeEventListener('smarthire:open-applications', openApplications) }, [])
  const openJob = (job) => setSelectedJob(job)
  let page
  if (loading) page = <div className="portal-loading"><span className="spinner large" /><p>Preparing your SmartHire workspace…</p></div>
  else if (isRecruiter) page = <RecruiterWorkspace tab={tab} setTab={setTab} user={user} profile={profile} setProfile={setProfile} jobs={jobs} applications={recruiterApplications} onUpdateApplication={handleRecruiterStatus} updatingApplicationId={updatingApplicationId} onSaveProfile={saveProfile} onPostJob={postJob} saving={saving} posting={posting} />
  else if (tab === 'home') page = <CandidateHome user={user} profile={profile} resumes={resumes} applications={applications} jobs={jobs} savedIds={savedIds} skills={skills} setTab={setTab} openJob={openJob} toggleSaved={toggleSaved} />
  else if (tab === 'jobs') page = <JobExplorer jobs={jobs} skills={skills} savedIds={savedIds} applications={applications} openJob={openJob} toggleSaved={toggleSaved} />
  else if (tab === 'applications') page = <ApplicationTracker applications={applications} jobs={jobs} resumes={resumes} onRefresh={() => setRefreshToken((current) => current + 1)} />
  else if (tab === 'resumes') page = <ResumeStudio user={user} profile={profile} resumes={resumes} draft={resumeDraft} setDraft={setResumeDraft} onUpload={handleUpload} onGenerate={handleGenerateResume} uploading={uploading} generating={generating} />
  else page = <CandidateProfile profile={profile} setProfile={setProfile} onSave={saveProfile} saving={saving} />
  return <main className="portal-shell"><aside className="portal-sidebar"><div><Brand /><p className="workspace-label">{isRecruiter ? 'RECRUITER WORKSPACE' : 'CANDIDATE WORKSPACE'}</p><nav>{tabs.map(([id, label, icon]) => <button type="button" key={id} className={tab === id ? 'active' : ''} onClick={() => { setTab(id); setSelectedJob(null) }}><span>{icon}</span>{label}</button>)}</nav></div><div className="sidebar-bottom"><div className="candidate-mini"><span>{initials(user.name)}</span><div><b>{user.name}</b><small>{isRecruiter ? 'Recruiter account' : 'Candidate account'}</small></div></div><button type="button" className="logout-button" onClick={onLogout}><span>↪</span> Sign out</button></div></aside><section className="portal-main"><header className="portal-topbar"><button type="button" className="mobile-brand" onClick={() => setTab(isRecruiter ? 'overview' : 'home')}><Brand /></button><div className="topbar-search"><span>⌕</span><input placeholder="Search jobs, companies or skills" onFocus={() => !isRecruiter && setTab('jobs')} /></div><div className="topbar-actions"><button type="button" className="notification-button" aria-label="Notifications">♧<i /></button><div className="topbar-user"><span>{initials(user.name)}</span><b>{user.name?.split(' ')[0]}</b></div></div></header><div className="portal-content"><Notice notice={notice} onDismiss={() => setNotice(null)} />{page}</div></section>{!isRecruiter && selectedJob && <div className="job-detail-backdrop" role="presentation" onMouseDown={() => setSelectedJob(null)}><div onMouseDown={(event) => event.stopPropagation()}><JobDetail job={selectedJob} saved={savedIds.includes(selectedJob.id)} applied={appliedJobIds.has(selectedJob.id)} match={jobMatch(selectedJob, skills)} onClose={() => setSelectedJob(null)} onApply={beginApply} onToggleSave={toggleSaved} /></div></div>}{!isRecruiter && <ApplyModal key={applyJob?.id ?? 'no-application'} job={applyJob} resumes={resumes} onClose={() => setApplyJob(null)} onApply={submitApplication} submitting={submittingApplication} />}</main>
}
